static void yc101_init(void)
{
    int i;
    struct dsi_cmd_packet yc101_sleep_out = {0x05,0x11, 0x00};
    struct dsi_cmd_packet yc101_display_on = {0x05,0x29, 0x00};

    for (i = 0; i < ARRAY_SIZE(yc101_cmd_list_2lane); i++) {
        dsi_write_cmd(&yc101_cmd_list_2lane[i]);
    }

    dsi_write_cmd(&yc101_sleep_out);
    usleep_range(120 * 1000, 120 * 1000);
    dsi_write_cmd(&yc101_display_on);
    usleep_range(20 * 1000, 20 * 1000);
}

static inline int m_gpio_request(int gpio, const char *name)
{
    if (gpio < 0)
        return 0;

    int ret = gpio_request(gpio, name);
    if (ret) {
        char buf[20];
        printk(KERN_ERR "yc101: failed to request %s: %s\n", name, gpio_to_str(gpio, buf));
        return ret;
    }

    return 0;
}

static inline void m_gpio_free(int gpio)
{
    if (gpio >= 0)
        gpio_free(gpio);
}

static inline void m_gpio_direction_output(int gpio, int value)
{
    if (gpio >= 0) {
        gpio_direction_output(gpio, value);
    }
}

static int yc101_power_on(struct lcdc *lcdc)
{
    if (yc101_regulator)
        regulator_enable(yc101_regulator);

    m_gpio_direction_output(gpio_lcd_power_en, 1);
    usleep_range(100 * 1000, 100 * 1000);

    m_gpio_direction_output(gpio_lcd_rst, 1);
    usleep_range(5 * 1000, 5 * 1000);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    usleep_range(1 * 1000, 1 * 1000);
    m_gpio_direction_output(gpio_lcd_rst, 1);
    usleep_range(10 * 1000, 10 * 1000);

    return 0;
}

static int yc101_power_off(struct lcdc *lcdc)
{
    m_gpio_direction_output(gpio_lcd_power_en, 0);

    if (yc101_regulator)
        regulator_disable(yc101_regulator);

    return 0;
}

